        fig: '<svg viewBox="0 0 400 300" xmlns="http://www.w3.org/2000/svg"><defs><marker id="ah" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="var(--ink)"/></marker></defs><rect x="150" y="15" width="100" height="40" rx="8" fill="var(--chip)" stroke="var(--ink)"/><text x="200" y="40" text-anchor="middle" font-size="14" fill="var(--ink)">肺</text><rect x="105" y="125" width="95" height="55" rx="6" fill="var(--ask)" stroke="var(--ink)"/><text x="152" y="150" text-anchor="middle" font-size="14" fill="var(--ink)">右心房</text><text x="152" y="170" text-anchor="middle" font-size="14" fill="var(--ink)">右心室</text><rect x="200" y="125" width="95" height="55" rx="6" fill="var(--warm)" stroke="var(--ink)"/><text x="247" y="150" text-anchor="middle" font-size="14" fill="var(--ink)">左心房</text><text x="247" y="170" text-anchor="middle" font-size="14" fill="var(--ink)">左心室</text><rect x="150" y="245" width="100" height="40" rx="8" fill="var(--chip)" stroke="var(--ink)"/><text x="200" y="270" text-anchor="middle" font-size="14" fill="var(--ink)">全身</text><line x1="140" y1="123" x2="168" y2="58" stroke="var(--ink)" stroke-width="2" marker-end="url(#ah)"/><line x1="232" y1="58" x2="260" y2="123" stroke="var(--ink)" stroke-width="2" marker-end="url(#ah)"/><line x1="260" y1="182" x2="232" y2="243" stroke="var(--ink)" stroke-width="2" marker-end="url(#ah)"/><line x1="168" y1="243" x2="140" y2="182" stroke="var(--ink)" stroke-width="2" marker-end="url(#ah)"/><text x="80" y="90" font-size="14" fill="var(--ink)">肺動脈</text><text x="262" y="90" font-size="14" fill="var(--ink)">肺静脈</text><text x="262" y="220" font-size="14" fill="var(--ink)">大動脈</text><text x="80" y="220" font-size="14" fill="var(--ink)">大静脈</text><text x="200" y="110" text-anchor="middle" font-size="14" fill="var(--ink)">肺循環</text><text x="200" y="215" text-anchor="middle" font-size="14" fill="var(--ink)">体循環</text></svg>'
