        fig: '<svg viewBox="0 0 400 300" xmlns="http://www.w3.org/2000/svg"><rect x="140" y="10" width="120" height="36" rx="8" fill="var(--chip)" stroke="var(--ink)"/><text x="200" y="34" text-anchor="middle" font-size="14" fill="var(--ink)">神経系</text><line x1="200" y1="46" x2="100" y2="80" stroke="var(--ink)"/><line x1="200" y1="46" x2="290" y2="80" stroke="var(--ink)"/><rect x="30" y="80" width="140" height="56" rx="8" fill="var(--accent)" stroke="var(--ink)"/><text x="100" y="104" text-anchor="middle" font-size="14" fill="var(--ink)">中枢神経系</text><text x="100" y="124" text-anchor="middle" font-size="14" fill="var(--ink)">脳・脊髄</text><rect x="220" y="80" width="140" height="36" rx="8" fill="var(--chip)" stroke="var(--ink)"/><text x="290" y="104" text-anchor="middle" font-size="14" fill="var(--ink)">末梢神経系</text><line x1="290" y1="116" x2="230" y2="160" stroke="var(--ink)"/><line x1="290" y1="116" x2="340" y2="160" stroke="var(--ink)"/><rect x="170" y="160" width="115" height="36" rx="8" fill="var(--ask)" stroke="var(--ink)"/><text x="227" y="184" text-anchor="middle" font-size="14" fill="var(--ink)">体性神経系</text><rect x="290" y="160" width="105" height="36" rx="8" fill="var(--warm)" stroke="var(--ink)"/><text x="342" y="184" text-anchor="middle" font-size="14" fill="var(--ink)">自律神経系</text><text x="227" y="222" text-anchor="middle" font-size="14" fill="var(--ink)">感覚神経</text><text x="227" y="244" text-anchor="middle" font-size="14" fill="var(--ink)">運動神経</text><text x="342" y="222" text-anchor="middle" font-size="14" fill="var(--ink)">交感神経</text><text x="342" y="244" text-anchor="middle" font-size="14" fill="var(--ink)">副交感神経</text><line x1="227" y1="196" x2="227" y2="206" stroke="var(--ink)"/><line x1="342" y1="196" x2="342" y2="206" stroke="var(--ink)"/></svg>'
